#!/usr/bin/env python3
"""Apply the count-only patch to a job3_validate.py.
   python3 apply_count_only_patch.py <in job3_validate.py> <out job3_validate.py>
Adds code only (removes nothing). Refuses a file it does not recognise."""
import sys

BLOCK = '# =============================================================================\n# COUNT-ONLY PATCH (checksum_mode=off): validate each table with COUNT(*) only.\n#   * no Spark / no S3 CSV read, no column checks; DSQL COUNT(*) vs DMS FullLoadRows\n#     (or discovery\'s saved full_load_rows)\n#   * own small range code (does NOT reuse the validation range builders)\n#   * the 300s limit: a count that hits the limit OR fails with XX000 "server unavailable" is\n#     split into key ranges; a range that fails the same way is halved; counts are summed\n#   * ONE boundary list per table, built once: only the first range is open at the bottom and\n#     only the last is open at the top, so rows outside the sampled min/max are still counted\n#   * runtime checks on every run: boundaries strictly increasing, ranges == boundaries + 1,\n#     every counted piece joins the next with no gap/overlap. If a check fails the count is NOT\n#     used (table passed with a WARNING, nothing compared) - a wrong number is never reported\n#   * other errors: retried COUNT_RETRIES times, COUNT_RETRY_WAIT seconds apart; if the count\n#     still cannot finish the table passes with a WARNING and the run moves on to CDC.\n#   * HARD TIME LIMIT: the whole count for a table (expected-count lookup, key bounds, every range,\n#     retries) runs in a worker thread and the caller stops waiting after COUNT_TABLE_BUDGET_SECONDS\n#     (900 = 15 min) even if a query is still running; the table then passes with a WARNING.\n#     A count that FINISHES and DISAGREES fails the table.\n# =============================================================================\nCOUNT_RETRIES = 3                  # retries per query for an error that is not a size problem\nCOUNT_RETRY_WAIT = 20              # seconds between those retries\nCOUNT_SPLIT_ROWS = 100_000_000     # expected rows at/above which we go straight to key ranges\nCOUNT_RANGE_ROWS = 20_000_000      # target rows per range (about 40s at ~60s per 30M rows)\nCOUNT_RANGE_THREADS = 4            # ranges counted at the same time\nCOUNT_MAX_HALVINGS = 40            # how many times one range may be halved after size errors\nCOUNT_UNKNOWN_TOTAL_ROWS = 600_000_000    # range sizing after a whole-table COUNT(*) was too big (or expected count unknown)\nCOUNT_TABLE_BUDGET_SECONDS = 900   # HARD wall-clock limit per table (15 min): then warn + go on to CDC\n\n\nclass CountRangeError(Exception):\n    """The count-only range math failed its own consistency check (never a data problem)."""\n\n\nclass CountSplit(Exception):\n    """A query was too big for DSQL (300s limit / server unavailable): split it and retry."""\n\n\nclass CountStop(Exception):\n    """Counting this table was stopped (time budget used up or another range failed)."""\n\n\ndef _cnt_q(col):\n    return \'"\' + str(col).replace(\'"\', \'""\') + \'"\'\n\n\ndef _cnt_lit(kind, v):\n    if kind == "integer":\n        return str(int(v))\n    h = format(int(v), "032x")\n    return "\'%s-%s-%s-%s-%s\'::uuid" % (h[0:8], h[8:12], h[12:16], h[16:20], h[20:32])\n\n\ndef _cnt_to_int(kind, v):\n    if kind == "integer":\n        return int(v)\n    return int(str(v).replace("-", "").strip().lower(), 16)\n\n\ndef _cnt_pred(col, kind, lo, hi):\n    p = []\n    if lo is not None:\n        p.append("%s >= %s" % (_cnt_q(col), _cnt_lit(kind, lo)))\n    if hi is not None:\n        p.append("%s < %s" % (_cnt_q(col), _cnt_lit(kind, hi)))\n    # A range with no bounds still must not count NULL-key rows: those are counted separately.\n    return " AND ".join(p) if p else "%s IS NOT NULL" % _cnt_q(col)\n\n\ndef _cnt_alive(ctx):\n    if ctx["abort"].is_set() or time.time() > ctx["deadline"]:\n        ctx["abort"].set()\n        raise CountStop("count-only stopped (time budget used up or another range failed)")\n\n\ndef _cnt_unavailable(e):\n    """DSQL \'XX000 / server unavailable\' - what a too-large scan can fail with instead of a timeout."""\n    s = ""\n    try:\n        a0 = e.args[0] if getattr(e, "args", None) else None\n        if isinstance(a0, dict):\n            if str(a0.get("C") or a0.get("code") or "") == "XX000":\n                return True\n            s = str(a0.get("M") or a0)\n        else:\n            s = str(a0 if a0 is not None else e)\n    except Exception:\n        s = str(e)\n    s = s.lower()\n    return "xx000" in s or "server unavailable" in s\n\n\ndef _cnt_run(schema, table, pred, ctx):\n    """One COUNT(*). Too big (300s limit / statement timeout / XX000 after retries) -> CountSplit\n    so the caller splits it. Any other error is retried COUNT_RETRIES times, then raised."""\n    attempt = 0\n    while True:\n        _cnt_alive(ctx)\n        try:\n            return int(_target_query(schema, table, pred, [])[0])\n        except Exception as e:\n            if is_txn_age_error(e):\n                raise CountSplit(str(e)[:200])\n            attempt += 1\n            if attempt > COUNT_RETRIES:\n                if _cnt_unavailable(e):\n                    raise CountSplit(str(e)[:200])\n                raise\n            print("    count-only retry %d/%d on %s.%s after %s: %s"\n                  % (attempt, COUNT_RETRIES, schema, table, type(e).__name__, str(e)[:150]))\n            time.sleep(max(0.0, min(COUNT_RETRY_WAIT, ctx["deadline"] - time.time())))\n\n\ndef _cnt_edge(schema, table, col, asc, ctx):\n    """Lowest (asc) or highest key, ignoring NULL keys (NULLs sort last on ASC, first on DESC)."""\n    sql = "SELECT %s FROM %s.%s WHERE %s IS NOT NULL ORDER BY %s %s LIMIT 1" % (\n        _cnt_q(col), schema, table, _cnt_q(col), _cnt_q(col), "ASC" if asc else "DESC")\n    attempt = 0\n    while True:\n        _cnt_alive(ctx)\n        conn = None\n        try:\n            conn = connect_dsql(autocommit=True)\n            cur = conn.cursor()\n            try:\n                cur.execute(sql)\n                r = cur.fetchone()\n            finally:\n                cur.close()\n            return None if (not r or r[0] is None) else r[0]\n        except Exception as e:\n            attempt += 1\n            if attempt > COUNT_RETRIES:\n                raise\n            print("    count-only retry %d/%d fetching key bounds on %s.%s after %s"\n                  % (attempt, COUNT_RETRIES, schema, table, type(e).__name__))\n            time.sleep(max(0.0, min(COUNT_RETRY_WAIT, ctx["deadline"] - time.time())))\n        finally:\n            try:\n                if conn is not None:\n                    conn.close()\n            except Exception:\n                pass\n\n\ndef _cnt_nullable(schema, table, col):\n    """False only when information_schema says the column is NOT NULL (primary-key columns are).\n    Any doubt -> True (the NULL-key rows then get counted)."""\n    conn = None\n    try:\n        conn = connect_dsql(autocommit=True)\n        cur = conn.cursor()\n        try:\n            cur.execute("SELECT is_nullable FROM information_schema.columns "\n                        "WHERE table_schema = %s AND table_name = %s AND column_name = %s",\n                        (schema, table, col))\n            r = cur.fetchone()\n        finally:\n            cur.close()\n        return not (r and str(r[0]).strip().upper() == "NO")\n    except Exception:\n        return True\n    finally:\n        try:\n            if conn is not None:\n                conn.close()\n        except Exception:\n            pass\n\n\ndef _cnt_plan(gmin, gmax, total, per):\n    """ONE boundary list for the whole table. Returns [(lo, hi, eff_lo, eff_hi), ...] where\n    lo/hi are the SQL bounds (None = open) and eff_lo/eff_hi are the finite bounds used only to\n    pick a split point. Only the first range has lo None and only the last has hi None."""\n    span = gmax - gmin + 1\n    n = max(1, -(-int(total) // max(1, int(per))))\n    n = min(n, span)\n    bounds = [gmin + (i * span) // n for i in range(1, n)]\n    prev = gmin\n    for bd in bounds:\n        if not (bd > prev and bd <= gmax):\n            raise CountRangeError("boundaries not strictly increasing inside (min, max]: %r" % (bounds[:5],))\n        prev = bd\n    edges = [None] + bounds + [None]\n    eff = [gmin] + bounds + [gmax + 1]\n    rngs = [(edges[i], edges[i + 1], eff[i], eff[i + 1]) for i in range(n)]\n    if len(rngs) != len(bounds) + 1:\n        raise CountRangeError("ranges (%d) != boundaries (%d) + 1" % (len(rngs), len(bounds)))\n    return rngs\n\n\ndef _cnt_leaf(schema, table, col, kind, lo, hi, elo, ehi, depth, leaves, ctx):\n    """Count one range; on a size error halve it (children share the parent\'s outer bounds)."""\n    try:\n        n = _cnt_run(schema, table, _cnt_pred(col, kind, lo, hi), ctx)\n        leaves.append((elo, ehi, lo, hi, n))\n        return\n    except CountSplit as e:\n        too_big = e\n    if depth >= COUNT_MAX_HALVINGS or (ehi - elo) < 2:\n        raise too_big\n    mid = elo + (ehi - elo) // 2\n    if not (elo < mid < ehi):\n        raise CountRangeError("bad split point %r in [%r, %r)" % (mid, elo, ehi))\n    print("    count-only %s.%s: range too big, halving (depth %d)" % (schema, table, depth + 1))\n    _cnt_leaf(schema, table, col, kind, lo, mid, elo, mid, depth + 1, leaves, ctx)\n    _cnt_leaf(schema, table, col, kind, mid, hi, mid, ehi, depth + 1, leaves, ctx)\n\n\ndef _cnt_verify(leaves, gmin, gmax):\n    """Every counted piece must join the next one exactly: no gap, no overlap, no repeat."""\n    if not leaves:\n        raise CountRangeError("no ranges were counted")\n    ls = sorted(leaves, key=lambda x: x[0])\n    if ls[0][0] != gmin or ls[0][2] is not None:\n        raise CountRangeError("first range is not open at the bottom / does not start at the minimum key")\n    if ls[-1][1] != gmax + 1 or ls[-1][3] is not None:\n        raise CountRangeError("last range is not open at the top / does not end past the maximum key")\n    for i, (elo, ehi, lo, hi, n) in enumerate(ls):\n        if not (elo < ehi):\n            raise CountRangeError("empty or inverted range [%r, %r)" % (elo, ehi))\n        if i > 0 and ls[i - 1][1] != elo:\n            raise CountRangeError("gap or overlap between ranges at %r (previous ends %r)" % (elo, ls[i - 1][1]))\n        if i > 0 and lo != elo:\n            raise CountRangeError("range %d lower bound %r differs from %r" % (i, lo, elo))\n        if i < len(ls) - 1 and hi != ehi:\n            raise CountRangeError("range %d upper bound %r differs from %r" % (i, hi, ehi))\n\n\ndef _cnt_ranged(schema, table, col, kind, expected, ctx, after_timeout=False):\n    lo_raw = _cnt_edge(schema, table, col, True, ctx)\n    hi_raw = _cnt_edge(schema, table, col, False, ctx)\n    nulls = _cnt_run(schema, table, "%s IS NULL" % _cnt_q(col), ctx) \\\n        if _cnt_nullable(schema, table, col) else 0\n    if lo_raw is None or hi_raw is None:\n        return nulls                                   # no non-NULL keys at all\n    gmin, gmax = _cnt_to_int(kind, lo_raw), _cnt_to_int(kind, hi_raw)\n    if gmax < gmin:\n        raise CountRangeError("maximum key %r is below minimum key %r" % (hi_raw, lo_raw))\n    # After a whole-table timeout the table is bigger than the expected count suggests (or the count\n    # was unknown): size the ranges for at least COUNT_UNKNOWN_TOTAL_ROWS so we do not start with one\n    # huge range that times out again and burns the time budget.\n    if after_timeout or not expected:\n        total = max(int(expected or 0), COUNT_UNKNOWN_TOTAL_ROWS)\n    else:\n        total = int(expected)\n    rngs = _cnt_plan(gmin, gmax, total, COUNT_RANGE_ROWS)\n    print("    count-only %s.%s: counting %d key range(s), %d at a time"\n          % (schema, table, len(rngs), COUNT_RANGE_THREADS))\n    per_range = [[] for _ in rngs]\n\n    def _one(i):\n        try:\n            _cnt_alive(ctx)\n            lo, hi, elo, ehi = rngs[i]\n            _cnt_leaf(schema, table, col, kind, lo, hi, elo, ehi, 0, per_range[i], ctx)\n        except BaseException:\n            ctx["abort"].set()          # stop the other ranges, do not let them run on\n            raise\n\n    errs = []\n    with ThreadPoolExecutor(max_workers=COUNT_RANGE_THREADS) as pool:\n        futs = [pool.submit(_one, i) for i in range(len(rngs))]\n        for f in futs:\n            try:\n                f.result()\n            except Exception as e:\n                errs.append(e)\n    if errs:\n        real = [e for e in errs if not isinstance(e, CountStop)]\n        raise (real or errs)[0]\n    leaves = [x for part in per_range for x in part]\n    _cnt_verify(leaves, gmin, gmax)\n    return sum(x[4] for x in leaves) + nulls\n\n\ndef _cnt_impl(label, dsql_schema, dsql_table, entry, meta, pk_cols, pk_meta, rangeable, pk_col, pk_kind, ctx):\n    _e = entry if isinstance(entry, dict) else {}\n    expected, basis = None, None\n    if DMS_TASK_ARN:\n        try:\n            _fs = (meta.get(\'dms_schema\') or _e.get(\'dms_schema\') or meta.get(\'dms_folder_schema\')\n                   or meta.get(\'source_schema\') or dsql_schema)\n            _ft = (meta.get(\'dms_table\') or _e.get(\'dms_table\') or meta.get(\'dms_folder_table\')\n                   or meta.get(\'source_table\') or dsql_table)\n            expected = dms_full_load_rows_for(make_boto_client(\'dms\'), DMS_TASK_ARN, _fs, _ft)\n            basis = "DMS FullLoadRows"\n        except Exception:\n            expected = None\n    if expected is None:\n        _v = _e.get(\'full_load_rows\')\n        if _v is None:\n            _v = meta.get(\'full_load_rows\')\n        if _v is not None:\n            expected, basis = int(_v), "discovery full_load_rows"\n    expected = int(expected) if expected is not None else None\n\n    # the column to split on: the validation key if it is rangeable, else a single-column key\n    # of a kind we can split (integer / uuid), whether or not the load kept it in the CSV\n    ck, kk = (pk_col, pk_kind) if rangeable else (None, None)\n    if ck is None and len(pk_cols or []) == 1 and (pk_meta or {}).get(\'pk_kind\') in ("integer", "uuid"):\n        ck, kk = pk_cols[0], pk_meta.get(\'pk_kind\')\n    can_range = bool(ck) and kk in ("integer", "uuid")\n\n    base = {"table": label, "ranges": 1, "checksum_mode": CHECKSUM_MODE, "columns_compared": 0,\n            "columns_differing": [], "mismatches": [], "mismatch_count": 0}\n    tgt, err = None, None\n    try:\n        if can_range and expected is not None and expected >= COUNT_SPLIT_ROWS:\n            # known big table (>= 100M rows expected): straight to key ranges, never a whole-table COUNT(*)\n            tgt = _cnt_ranged(dsql_schema, dsql_table, ck, kk, expected, ctx)\n        else:\n            try:\n                tgt = _cnt_run(dsql_schema, dsql_table, None, ctx)\n            except CountSplit:\n                if not can_range:\n                    raise\n                print("    count-only %s: whole-table COUNT(*) too big for DSQL; using key ranges" % label)\n                tgt = _cnt_ranged(dsql_schema, dsql_table, ck, kk, expected, ctx, after_timeout=True)\n    except CountRangeError as e:\n        msg = ("COUNT-ONLY RANGE CHECK FAILED (%s); the count was NOT used, table passed with a "\n               "WARNING, nothing compared" % e)\n        print("    ⚠️  count-only [%s]: %s" % (label, msg))\n        return dict(base, status="match", source_rows=expected, target_rows=None,\n                    warning=msg, notes=["COUNT-ONLY: " + msg])\n    except Exception as e:\n        err = e\n\n    if ctx.get("gave_up"):\n        return None                       # the caller already returned its own TIMED OUT warning\n    if isinstance(err, CountStop):\n        err = Exception("COUNT TIMED OUT after the %g-second per-table limit" % COUNT_TABLE_BUDGET_SECONDS)\n    if err is not None:\n        msg = ("COUNT NOT COMPLETED (%s: %s); table passed with a WARNING so the run can move on "\n               "to CDC" % (type(err).__name__, str(err)[:200]))\n        print("    ⚠️  count-only [%s]: %s" % (label, msg))\n        return dict(base, status="match", source_rows=expected, target_rows=None,\n                    warning=msg, notes=["COUNT-ONLY: " + msg])\n    if expected is None:\n        msg = "DSQL count %s; no DMS/discovery row count to compare against (not compared)" % format(tgt, ",")\n        print("    ⚠️  count-only [%s]: %s" % (label, msg))\n        return dict(base, status="match", source_rows=None, target_rows=tgt,\n                    warning=msg, notes=["COUNT-ONLY: " + msg])\n    tol = float(COUNT_MISMATCH_TOLERANCE or 0)\n    ok = abs(tgt - expected) <= tol\n    print("    count-only [%s]: DSQL=%s vs %s=%s -> %s"\n          % (label, format(tgt, ","), basis, format(expected, ","), "OK" if ok else "MISMATCH"))\n    mism = [] if ok else [{"range": ["whole table"], "type": "COUNT_DIFF",\n                           "source": expected, "target": tgt}]\n    return dict(base, status="match" if ok else "mismatch", source_rows=expected, target_rows=tgt,\n                mismatches=mism, mismatch_count=len(mism),\n                notes=["COUNT-ONLY: DSQL COUNT(*) vs %s" % basis])\n\n\ndef count_only_validate(label, dsql_schema, dsql_table, entry, meta, pk_cols, pk_meta, rangeable, pk_col, pk_kind):\n    """Returns a result dict, or None when checksum_mode is not \'off\' (normal validation runs).\n    Never raises: an unexpected problem inside this patch passes the table with a WARNING."""\n    if CHECKSUM_MODE != "off":\n        return None\n    ctx = {"abort": threading.Event(), "deadline": time.time() + COUNT_TABLE_BUDGET_SECONDS}\n    runner = ThreadPoolExecutor(max_workers=1)\n    try:\n        fut = runner.submit(_cnt_impl, label, dsql_schema, dsql_table, entry, meta, pk_cols, pk_meta,\n                            rangeable, pk_col, pk_kind, ctx)\n        try:\n            return fut.result(timeout=COUNT_TABLE_BUDGET_SECONDS)\n        except Exception as e:\n            import concurrent.futures as _cf\n            if not isinstance(e, _cf.TimeoutError):\n                raise\n            ctx["gave_up"] = True        # the abandoned worker thread must not log a second warning\n            ctx["abort"].set()           # background queries stop at their next step\n            msg = ("COUNT TIMED OUT after the %g-second per-table limit; table passed with a "\n                   "WARNING so the run can move on to CDC, nothing was compared" % COUNT_TABLE_BUDGET_SECONDS)\n            print("    ⚠️  count-only [%s]: %s" % (label, msg))\n            return {"table": label, "status": "match", "ranges": 1, "checksum_mode": CHECKSUM_MODE,\n                    "columns_compared": 0, "columns_differing": [], "mismatches": [], "mismatch_count": 0,\n                    "source_rows": None, "target_rows": None, "warning": msg, "notes": ["COUNT-ONLY: " + msg]}\n    except Exception as e:\n        msg = ("COUNT-ONLY INTERNAL ERROR (%s: %s); table passed with a WARNING, nothing was "\n               "compared" % (type(e).__name__, str(e)[:200]))\n        print("    ⚠️  count-only [%s]: %s" % (label, msg))\n        return {"table": label, "status": "match", "ranges": 1, "checksum_mode": CHECKSUM_MODE,\n                "columns_compared": 0, "columns_differing": [], "mismatches": [], "mismatch_count": 0,\n                "source_rows": None, "target_rows": None, "warning": msg,\n                "notes": ["COUNT-ONLY: " + msg]}\n    finally:\n        ctx["abort"].set()\n        runner.shutdown(wait=False)\n\n\n'
CALL = '    _co = count_only_validate(label, dsql_schema, dsql_table, entry, meta,\n                              pk_cols, pk_meta, rangeable, pk_col, pk_kind)\n    if _co is not None:\n        return _co\n'
A1 = 'def validate_one_table(s3, entry):'
A2 = '        return {"table": label, "status": "error", "reason": "target table not found in DSQL"}\n'
REQUIRED = ["pk_meta = meta.get('primary_key', {}) or {}", "pk_cols = pk_meta.get('columns') or []", 'rangeable = len(pk_cols) == 1', 'def is_txn_age_error(', 'def _target_query(', 'def connect_dsql(', 'def dms_full_load_rows_for(', 'def make_boto_client(', 'from concurrent.futures import', 'import threading', 'import time', 'COUNT_MISMATCH_TOLERANCE = 0', 'DMS_TASK_ARN = None', 'CHECKSUM_MODE = "aggregate"']


def apply(in_path, out_path):
    src = open(in_path).read()
    miss = [r for r in REQUIRED if r not in src]
    assert not miss, "this does not look like the expected job3_validate.py; missing: %s" % miss
    assert src.count(A1) == 1, "anchor 1 not found exactly once - is this job3_validate.py?"
    assert src.count(A2) == 1, "anchor 2 not found exactly once - is this job3_validate.py?"
    assert "count_only_validate" not in src, "already patched"
    new = src.replace(A1, BLOCK + A1).replace(A2, A2 + "\n" + CALL)
    compile(new, "job3_validate.py", "exec")
    open(out_path, "w").write(new)
    return new


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    apply(sys.argv[1], sys.argv[2])
    print("patched ->", sys.argv[2])
